async function syncDealsIncremental(client, db) {
  const cursor = await getState(db, "deals_cursor");
  const result = { changedDealIds: [], changedContactIds: [] };
  const seenAt = (/* @__PURE__ */ new Date()).toISOString();
  let maxUpdated = cursor;
  for await (const page of client.listDeals(cursor ? { updated_at_start: minusMinutes(cursor, 5) } : {})) {
    await batchRun(db, page.flatMap((d) => upsertDeal(db, d, seenAt)));
    for (const d of page) {
      result.changedDealIds.push(d.id);
      if (d.contact) result.changedContactIds.push(d.contact.id);
      if (!maxUpdated || d.updated_at > maxUpdated) maxUpdated = d.updated_at;
    }
  }
  if (maxUpdated) await setState(db, "deals_cursor", maxUpdated);
  return result;
}
async function reconcileDealsFull(client, db, opts = {}) {
  const runStart = opts.runStart ?? (/* @__PURE__ */ new Date()).toISOString();
  let page = opts.fromPage ?? 1;
  for await (const rows of client.listDeals({}, page)) {
    await batchRun(db, rows.flatMap((d) => upsertDeal(db, d, runStart)));
    page++;
    await opts.onPage?.(page);
  }
  await db.prepare("UPDATE deals SET deleted = 1 WHERE last_seen_at IS NULL OR last_seen_at < ?").bind(runStart).run();
}

// src/lib/attribution.ts
function attributeMessage(msg, chat, openDealOwnerId) {
  if (msg.type !== "USER") return { attributed_user_id: null, attribution: "none" };
  if (msg.user_id) return { attributed_user_id: msg.user_id, attribution: "direct" };
  if (chat.user_id) return { attributed_user_id: chat.user_id, attribution: "chat" };
  if (openDealOwnerId) return { attributed_user_id: openDealOwnerId, attribution: "deal" };
  return { attributed_user_id: null, attribution: "none" };
}

// src/sync/messages.ts
async function syncMessages(client, db, windowStart2) {
  const { results: pending } = await db.prepare(
    `SELECT id, contact_id, user_id, last_message_at FROM chats
       WHERE last_message_at >= ? AND (messages_synced_until IS NULL OR last_message_at > messages_synced_until)
       ORDER BY last_message_at ASC`
  ).bind(windowStart2).all();
  const done = [];
  for (const chat of pending) {
    try {
      await syncChatMessages(client, db, chat, windowStart2);
      done.push(chat.id);
    } catch (e) {
      if (e instanceof BudgetExhausted) break;
      throw e;
    }
  }
  return done;
}
async function syncChatMessages(client, db, chat, windowStart2) {
  const owner = chat.contact_id ? await db.prepare("SELECT user_id FROM deals WHERE contact_id = ? AND status = 'OPEN' AND deleted = 0 ORDER BY updated_at DESC LIMIT 1").bind(chat.contact_id).first() : null;
  const known = new Set(
    (await db.prepare("SELECT id FROM messages WHERE chat_id = ?").bind(chat.id).all()).results.map((r) => r.id)
  );
  const stmts = [];
  outer: for await (const page of client.listMessagesByChat(chat.id)) {
    for (const m of page) {
      if (known.has(m.id) || m.created_at < windowStart2) break outer;
      const a = attributeMessage(m, chat, owner?.user_id ?? null);
      stmts.push(
        db.prepare(
          `INSERT INTO messages (id, chat_id, type, content_type, sender_user_id, attributed_user_id, attribution, created_at, created_day_sp)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
             ON CONFLICT(id) DO UPDATE SET attributed_user_id = excluded.attributed_user_id, attribution = excluded.attribution`
        ).bind(m.id, chat.id, m.type, m.content_type ?? null, m.user_id ?? null, a.attributed_user_id, a.attribution, m.created_at, toDaySP(m.created_at))
      );
    }
  }
  stmts.push(db.prepare("UPDATE chats SET messages_synced_until = ? WHERE id = ?").bind(chat.last_message_at, chat.id));
  await batchRun(db, stmts);
}

// src/meta/client.ts
var GRAPH = "https://graph.facebook.com/v24.0";
var MetaApiError = class extends Error {
  constructor(code, message) {
    super(`Meta API: ${message}`);
    this.code = code;
  }
  code;
};
function leadsOf(row) {
  const a = row.actions?.find((x) => x.action_type === "lead") ?? row.actions?.find((x) => x.action_type === "onsite_conversion.lead_grouped");
  return a ? Math.round(Number(a.value)) : 0;
}
function actionOf(list, ...types) {
  for (const t of types) {
    const a = list?.find((x) => x.action_type === t);
    if (a) return Number(a.value) || 0;
  }
  return 0;
}
function purchasesOf(row) {
  const types = ["offsite_conversion.fb_pixel_purchase", "purchase", "omni_purchase"];
  return { count: Math.round(actionOf(row.actions, ...types)), value: actionOf(row.action_values, ...types) };
}
var MetaClient = class {
  constructor(token, onCall = () => {
  }) {
    this.token = token;
    this.onCall = onCall;
  }
  token;
  onCall;
  async get(url) {
    this.onCall();
    const res = await fetch(url, { headers: { Authorization: `Bearer ${this.token}` } });
    const body = await res.json();
    if (!res.ok || body.error) throw new MetaApiError(body.error?.code, body.error?.message ?? `HTTP ${res.status}`);
    return body;
  }
  async all(first) {
    const out = [];
    let next = first;
    while (next) {
      const page = await this.get(next);
      out.push(...page.data ?? []);
      next = page.paging?.next;
    }
    return out;
  }
  adAccounts() {
    return this.all(`${GRAPH}/me/adaccounts?fields=id,name,account_status&limit=100`);
  }
  /** Daily ad-level insights between two account-timezone days (inclusive). */
  insights(accountId, since, until) {
    const fields = "date_start,account_id,campaign_id,campaign_name,adset_id,adset_name,ad_id,ad_name,spend,impressions,clicks,inline_link_clicks,actions,action_values";
    const range = encodeURIComponent(JSON.stringify({ since, until }));
    return this.all(`${GRAPH}/${accountId}/insights?level=ad&time_increment=1&time_range=${range}&fields=${fields}&limit=500`);
  }
  /** Ads by id (40 per call) with a 128px thumbnail and the shareable preview link. */
  async adsByIds(ids) {
    const fields = "id,name,adset_id,campaign_id,effective_status,creative.thumbnail_width(128).thumbnail_height(128){thumbnail_url},preview_shareable_link";
    const out = [];
    for (let i = 0; i < ids.length; i += 40) {
      const chunk = ids.slice(i, i + 40).map(encodeURIComponent).join(",");
      const res = await this.get(`${GRAPH}/?ids=${chunk}&fields=${encodeURIComponent(fields)}`);
      out.push(...Object.values(res));
    }
    return out;
  }
};

// src/sync/meta.ts
var EVERY_MINUTES = 60;
var BACKFILL_DAYS = 90;
var REFRESH_DAYS = 3;
async function syncMeta(env2, now, onCall) {
  if (!env2.META_API_TOKEN) return "skipped";
  const db = env2.DB;
  const last = await getState(db, "meta_last_sync");
  if (last && now.getTime() - new Date(last).getTime() < EVERY_MINUTES * 6e4) return "skipped";
  const client = new MetaClient(env2.META_API_TOKEN, onCall);
  const today = todaySP(now);
  const since = last ? addDays(today, -REFRESH_DAYS) : addDays(today, -BACKFILL_DAYS);
  try {
    const accounts = (await client.adAccounts()).filter((a) => a.account_status === 1);
    for (const acc of accounts) {
      const rows = await client.insights(acc.id, since, today);
      await batchRun(
        db,
        rows.map(
          (r) => db.prepare(
            `INSERT INTO meta_insights (ad_id, date, account_id, campaign_id, campaign_name, adset_id, adset_name, ad_name, spend, impressions, clicks, leads,
                 link_clicks, landing_page_views, video_3s, purchases, purchase_value)
               VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
               ON CONFLICT(ad_id, date) DO UPDATE SET campaign_id = excluded.campaign_id, campaign_name = excluded.campaign_name,
                 adset_id = excluded.adset_id, adset_name = excluded.adset_name, ad_name = excluded.ad_name, spend = excluded.spend,
                 impressions = excluded.impressions, clicks = excluded.clicks, leads = excluded.leads, link_clicks = excluded.link_clicks,
                 landing_page_views = excluded.landing_page_views, video_3s = excluded.video_3s, purchases = excluded.purchases,
                 purchase_value = excluded.purchase_value`
          ).bind(
            r.ad_id,
            r.date_start,
            acc.id,
            r.campaign_id ?? null,
            r.campaign_name ?? null,
            r.adset_id ?? null,
            r.adset_name ?? null,
            r.ad_name ?? null,
            Number(r.spend ?? 0),
            Number(r.impressions ?? 0),
            Number(r.clicks ?? 0),
            leadsOf(r),
            Number(r.inline_link_clicks ?? 0),
            Math.round(actionOf(r.actions, "landing_page_view", "omni_landing_page_view")),
            Math.round(actionOf(r.actions, "video_view")),
            purchasesOf(r).count,
            purchasesOf(r).value
          )
        )
      );
      const ads = await client.adsByIds([...new Set(rows.map((r) => r.ad_id))]);
      await batchRun(
        db,
        ads.map(
          (a) => db.prepare(
            `INSERT INTO meta_ads (ad_id, account_id, name, adset_id, campaign_id, status, thumbnail_url, preview_url) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
               ON CONFLICT(ad_id) DO UPDATE SET name = excluded.name, adset_id = excluded.adset_id, campaign_id = excluded.campaign_id,
                 status = excluded.status, thumbnail_url = excluded.thumbnail_url, preview_url = excluded.preview_url`
          ).bind(a.id, acc.id, a.name ?? null, a.adset_id ?? null, a.campaign_id ?? null, a.effective_status ?? null, a.creative?.thumbnail_url ?? null, a.preview_shareable_link ?? null)
        )
      );
    }
    await setState(db, "meta_last_sync", now.toISOString());
    await setState(db, "meta_last_error", null);
    return "ok";
  } catch (e) {
    await setState(db, "meta_last_error", JSON.stringify({ at: now.toISOString(), message: e instanceof Error ? e.message : String(e) }));
    return "error";
  }
}

// src/sync/reference.ts
async function syncReference(client, db) {
  const [groups, origins, users, accounts, lostStatuses] = await Promise.all([
    client.listGroups(),
    client.listOrigins(),
    client.listUsers(),
    client.listChannelAccounts(),
    client.listLostStatuses()
  ]);
  const stmts = [];
  for (const g of groups) {
    stmts.push(db.prepare("INSERT INTO groups (id, name) VALUES (?, ?) ON CONFLICT(id) DO UPDATE SET name = excluded.name").bind(g.id, g.name));
  }
  for (const o of origins) {
    if (o.group) {
      stmts.push(
        db.prepare("INSERT INTO groups (id, name) VALUES (?, ?) ON CONFLICT(id) DO UPDATE SET name = excluded.name").bind(o.group.id, o.group.name)
      );
    }
    stmts.push(
      db.prepare(
        `INSERT INTO origins (id, name, group_id, archived_at) VALUES (?, ?, ?, ?)
           ON CONFLICT(id) DO UPDATE SET name = excluded.name, group_id = excluded.group_id, archived_at = excluded.archived_at`
      ).bind(o.id, o.name, o.group?.id ?? null, o.archived_at ?? null)
    );
    for (const s of o.stages ?? []) {
      stmts.push(
        db.prepare(
          `INSERT INTO stages (id, origin_id, label, "order", type) VALUES (?, ?, ?, ?, ?)
             ON CONFLICT(id) DO UPDATE SET origin_id = excluded.origin_id, label = excluded.label, "order" = excluded."order", type = excluded.type`
        ).bind(s.id, o.id, s.label, s.order ?? null, s.type ?? null)
      );
    }
  }
  stmts.push(db.prepare("UPDATE users SET active = 0"));
  for (const u of users) {
    const name = [u.first_name, u.last_name].filter(Boolean).join(" ").replace(/\s+/g, " ").trim() || u.email || u.id;
    stmts.push(
      db.prepare(
        `INSERT INTO users (id, name, email, active) VALUES (?, ?, ?, 1)
           ON CONFLICT(id) DO UPDATE SET name = excluded.name, email = excluded.email, active = 1`
      ).bind(u.id, name, u.email ?? null)
    );
  }
  for (const l of lostStatuses) {
    stmts.push(db.prepare("INSERT INTO lost_statuses (id, name) VALUES (?, ?) ON CONFLICT(id) DO UPDATE SET name = excluded.name").bind(l.id, l.name));
  }
  for (const a of accounts) {
    stmts.push(
      db.prepare(
        `INSERT INTO channel_accounts (id, name, type, status) VALUES (?, ?, ?, ?)
           ON CONFLICT(id) DO UPDATE SET name = excluded.name, type = excluded.type, status = excluded.status`
      ).bind(a.id, a.name, a.type, a.status)
    );
  }
  await batchRun(db, stmts);
}

// src/sync/run.ts
function windowStart(env2, now) {
  return new Date(now.getTime() - getConfig(env2).messageWindowDays * 864e5).toISOString();
}
async function recordError(db, e) {
  await setState(db, "last_error", JSON.stringify({ at: (/* @__PURE__ */ new Date()).toISOString(), message: e instanceof Error ? e.message : String(e) }));
}
async function runIncremental(env2, opts = {}) {
  const now = opts.now ?? /* @__PURE__ */ new Date();
  const budget = new Budget(opts.budget ?? 800, opts.deadline);
  const client = new ClintClient(env2.CLINT_API_TOKEN, budget);
  const db = env2.DB;
  const start = windowStart(env2, now);
  try {
    await syncReference(client, db);
    await syncDealsIncremental(client, db);
    await syncContacts(client, db, { full: false });
    await syncChats(client, db, start);
    await syncMessages(client, db, start);
    await recomputeReplyState(db);
    await syncMeta(env2, now, () => budget.used++);
    const pending = await db.prepare("SELECT COUNT(*) AS n FROM chats WHERE last_message_at >= ? AND (messages_synced_until IS NULL OR last_message_at > messages_synced_until)").bind(start).first();
    await setState(db, "last_success_at", now.toISOString());
    await setState(db, "last_error", null);
    return { complete: (pending?.n ?? 0) === 0, calls: budget.used };
  } catch (e) {
    if (e instanceof BudgetExhausted) {
      await recomputeReplyState(db);
      await setState(db, "last_success_at", now.toISOString());
      await setState(db, "last_error", null);
      return { complete: false, calls: budget.used };
    }
    await recordError(db, e);
    throw e;
  }
}
async function runNightly(env2, opts = {}) {
  const now = opts.now ?? /* @__PURE__ */ new Date();
  const client = new ClintClient(env2.CLINT_API_TOKEN, new Budget(opts.budget ?? Number.POSITIVE_INFINITY, opts.deadline));
  const db = env2.DB;
  const day = todaySP(now);
  const raw = await getState(db, "nightly");
  let st = raw ? JSON.parse(raw) : { day: "", runStart: "", step: "done", page: 1 };
  if (st.day !== day) st = { day, runStart: now.toISOString(), step: "deals", page: 1 };
  if (st.step === "done") return true;
  const save = () => setState(db, "nightly", JSON.stringify(st));
  try {
    if (st.step === "deals") {
      await reconcileDealsFull(client, db, {
        runStart: st.runStart,
        fromPage: Math.max(1, st.page - 1),
        onPage: async (p) => {
          st.page = p;
          await save();
        }
      });
      st = { ...st, step: "contacts", page: 1 };
      await save();
    }
    if (st.step === "contacts") {
      await syncContacts(client, db, {
        full: true,
        fromPage: Math.max(1, st.page - 1),
        onPage: async (p) => {
          st.page = p;
          await save();
        }
      });
      await db.prepare("DELETE FROM messages WHERE created_at < ?").bind(windowStart(env2, now)).run();
      await recomputeReplyState(db);
      st = { ...st, step: "done" };
      await save();
    }
    return true;
  } catch (e) {
    if (e instanceof BudgetExhausted) return false;
    await recordError(db, e);
    throw e;
  }
}

// src/job.ts
function snapshotConfig(env2) {
  return {
    BUSINESS_HOURS: env2.BUSINESS_HOURS,
    NO_REPLY_MINUTES: env2.NO_REPLY_MINUTES,
    MESSAGE_WINDOW_DAYS: env2.MESSAGE_WINDOW_DAYS,
    PROFILE_FIELDS: env2.PROFILE_FIELDS,
    CLINT_DEAL_URL_TEMPLATE: env2.CLINT_DEAL_URL_TEMPLATE ?? "",
    CLINT_CHAT_URL_TEMPLATE: env2.CLINT_CHAT_URL_TEMPLATE ?? ""
  };
}
async function runSyncJob(env2, mode, deadline, now = /* @__PURE__ */ new Date()) {
  return mode === "nightly" ? { nightlyDone: await runNightly(env2, { now, deadline }) } : await runIncremental(env2, { now, deadline });
}
function snapshotText(env2) {
  return buildSnapshotText(env2.DB, snapshotConfig(env2), getConfig(env2).profileFields);
}
async function uploadSnapshot(supabaseUrl, serviceKey, objectName, body) {
  const bytes = new TextEncoder().encode(body);
  for (let attempt = 1; ; attempt++) {
    const res = await fetch(`${supabaseUrl}/storage/v1/object/dash/${objectName}`, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${serviceKey}`,
        apikey: serviceKey,
        "Content-Type": "application/json",
        "x-upsert": "true",
        "cache-control": "max-age=60"
      },
      body: bytes
    });
    if (res.ok) return bytes.length;
    const text = (await res.text()).replace(/\s+/g, " ").slice(0, 160);
    if (attempt >= 3 || res.status < 500) throw new Error(`Storage upload ${res.status}: ${text}`);
    await new Promise((r) => setTimeout(r, 2e3 * attempt));
  }
}

// functions-src/sync.ts
var env = (name) => Deno.env.get(name) ?? "";
var SYNC_SECONDS = 100;
Deno.serve(async (req) => {
  if (!env("CRON_KEY") || req.headers.get("x-cron-key") !== env("CRON_KEY")) return new Response("forbidden", { status: 403 });
  const url = new URL(req.url);
  const step = url.searchParams.get("step") === "snapshot" ? "snapshot" : "sync";
  const mode = url.searchParams.get("mode") === "nightly" ? "nightly" : "incremental";
  const { db, end } = pgDb(env("SUPABASE_DB_URL"));
  const appEnv = {
    DB: db,
    CLINT_API_TOKEN: env("CLINT_API_TOKEN"),
    META_API_TOKEN: env("META_API_TOKEN") || void 0,
    BUSINESS_HOURS: env("BUSINESS_HOURS"),
    NO_REPLY_MINUTES: env("NO_REPLY_MINUTES"),
    MESSAGE_WINDOW_DAYS: env("MESSAGE_WINDOW_DAYS"),
    PROFILE_FIELDS: env("PROFILE_FIELDS"),
    CLINT_DEAL_URL_TEMPLATE: env("CLINT_DEAL_URL_TEMPLATE"),
    CLINT_CHAT_URL_TEMPLATE: env("CLINT_CHAT_URL_TEMPLATE")
  };
  const started = Date.now();
  try {
    if (step === "snapshot") {
      const json = await snapshotText(appEnv);
      const bytes = await uploadSnapshot(env("SUPABASE_URL"), env("SUPABASE_SERVICE_ROLE_KEY"), `${env("SNAPSHOT_KEY")}.json`, json);
      return Response.json({ step, bytes, ms: Date.now() - started });
    }
    const sync = await runSyncJob(appEnv, mode, started + SYNC_SECONDS * 1e3);
    await end();
    const snap = await fetch(`${env("SUPABASE_URL")}/functions/v1/sync?step=snapshot`, { method: "POST", headers: { "x-cron-key": env("CRON_KEY") } });
    return Response.json({ step, mode, sync, ms: Date.now() - started, snapshot: snap.ok ? await snap.json() : `${snap.status} ${await snap.text()}` });
  } catch (e) {
    console.error(e);
    return Response.json({ error: e instanceof Error ? e.message : String(e) }, { status: 500 });
  } finally {
    await end().catch(() => {
    });
  }
});
